import { TONES, type SoundCue } from "./feedback-sounds";

export type FeedbackCue = "selection" | SoundCue;
export function isSoundCue(cue: FeedbackCue): cue is SoundCue { return cue !== "selection"; }

export type FeedbackPlayer = {
  pause: () => void;
  play: () => void;
  seekTo: (seconds: number) => Promise<void>;
  release: () => void;
};

type Dependencies = {
  configure: () => Promise<void>;
  createPlayer: (cue: SoundCue) => FeedbackPlayer | Promise<FeedbackPlayer>;
  onError?: (error: unknown) => void;
};

/** Latest outcome wins. Pending seeks cannot play after mute, background or disposal. */
export function createFeedbackAudio({ configure, createPlayer, onError = () => undefined }: Dependencies) {
  const players = new Map<SoundCue, FeedbackPlayer>();
  let disposed = false;
  let enabled = false;
  let active = true;
  let revision = 0;
  let preparation: Promise<void> | null = null;
  let playback = Promise.resolve();
  const allowed = () => !disposed && enabled && active;
  const safely = (action: () => void) => { try { action(); } catch (error) { onError(error); } };
  const pauseAll = () => { for (const player of players.values()) safely(() => player.pause()); };
  const releaseAll = () => {
    for (const player of players.values()) safely(() => player.release());
    players.clear();
  };

  function prepare(): Promise<void> {
    if (!allowed() || players.size === Object.keys(TONES).length) return Promise.resolve();
    if (preparation) return preparation;
    preparation = Promise.resolve().then(async () => {
      await configure();
      for (const cue of Object.keys(TONES) as SoundCue[]) {
        if (!allowed()) return;
        if (players.has(cue)) continue;
        const player = await createPlayer(cue);
        // A native player may finish loading after the provider has gone away.
        if (!allowed()) { safely(() => player.release()); return; }
        players.set(cue, player);
      }
    }).catch((error) => {
      releaseAll();
      if (!disposed) onError(error);
    }).finally(() => { preparation = null; });
    return preparation;
  }

  function play(cue: SoundCue): Promise<void> {
    const request = ++revision;
    pauseAll();
    if (!allowed()) return Promise.resolve();
    const current = () => request === revision && allowed();
    playback = playback.then(async () => {
      if (!current()) return;
      await prepare();
      if (!current()) return;
      const player = players.get(cue);
      if (!player) return;
      await player.seekTo(0);
      if (!current()) return;
      player.play();
    }).catch((error) => { if (!disposed) onError(error); });
    return playback;
  }

  return {
    prepare,
    play,
    setEnabled(value: boolean) {
      enabled = value;
      revision += 1;
      if (!allowed()) pauseAll();
      else void prepare();
    },
    setActive(value: boolean) {
      active = value;
      revision += 1;
      if (!allowed()) pauseAll();
      else void prepare();
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      revision += 1;
      pauseAll();
      releaseAll();
    },
  };
}

/** Serialise writes per preference so rapid toggles persist the latest choice. */
export function createPreferenceWriter(write: (key: string, value: string) => Promise<void>, onError: (error: unknown) => void) {
  const pending = new Map<string, Promise<void>>();
  return (key: string, value: string) => {
    const task = (pending.get(key) ?? Promise.resolve())
      .then(() => write(key, value))
      .catch(onError);
    pending.set(key, task);
    void task.then(() => { if (pending.get(key) === task) pending.delete(key); });
    return task;
  };
}

export type SoundCue = "correct" | "review" | "incorrect" | "complete";

export type Tone = {
  frequency: number;
  durationMs: number;
  gapMs?: number;
  gain?: number;
};

export const SAMPLE_RATE = 22_050;

// Selection is deliberately haptic-only. Audible cues are reserved for outcomes
// and completion so they remain informative rather than becoming tap noise.
export const TONES: Record<SoundCue, Tone[]> = {
  correct: [
    { frequency: 523.25, durationMs: 62, gapMs: 14, gain: 0.19 },
    { frequency: 659.25, durationMs: 105, gain: 0.20 },
  ],
  review: [
    { frequency: 493.88, durationMs: 70, gapMs: 12, gain: 0.14 },
    { frequency: 440, durationMs: 100, gain: 0.13 },
  ],
  incorrect: [
    { frequency: 392, durationMs: 70, gapMs: 14, gain: 0.13 },
    { frequency: 329.63, durationMs: 110, gain: 0.12 },
  ],
  complete: [
    { frequency: 523.25, durationMs: 72, gapMs: 14, gain: 0.18 },
    { frequency: 659.25, durationMs: 82, gapMs: 14, gain: 0.19 },
    { frequency: 783.99, durationMs: 150, gain: 0.20 },
  ],
};

function writeAscii(view: DataView, offset: number, value: string) {
  for (let index = 0; index < value.length; index += 1) view.setUint8(offset + index, value.charCodeAt(index));
}

export function writeWav(notes: Tone[]) {
  // Round each segment ONCE and reuse it for allocation AND writing. Rounding
  // the combined duration under-allocated the old correct/completion buffers.
  const segments = notes.map((note) => ({
    ...note,
    noteSamples: Math.ceil(note.durationMs * SAMPLE_RATE / 1000),
    gapSamples: Math.ceil((note.gapMs ?? 0) * SAMPLE_RATE / 1000),
  }));
  if (segments.some((note) => !Number.isFinite(note.frequency) || note.frequency <= 0 ||
    note.frequency >= SAMPLE_RATE / 2 || !Number.isFinite(note.noteSamples) ||
    note.noteSamples < 1 || !Number.isFinite(note.gapSamples) || note.gapSamples < 0 ||
    !Number.isFinite(note.gain ?? 0.16))) throw new RangeError("Invalid feedback tone");
  const totalSamples = segments.reduce((sum, note) => sum + note.noteSamples + note.gapSamples, 0);
  if (totalSamples > SAMPLE_RATE * 5) throw new RangeError("Feedback must stay under five seconds");
  const bytes = new Uint8Array(44 + totalSamples * 2);
  const view = new DataView(bytes.buffer);
  writeAscii(view, 0, "RIFF");
  view.setUint32(4, 36 + totalSamples * 2, true);
  writeAscii(view, 8, "WAVE");
  writeAscii(view, 12, "fmt ");
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, 1, true);
  view.setUint32(24, SAMPLE_RATE, true);
  view.setUint32(28, SAMPLE_RATE * 2, true);
  view.setUint16(32, 2, true);
  view.setUint16(34, 16, true);
  writeAscii(view, 36, "data");
  view.setUint32(40, totalSamples * 2, true);

  let outputIndex = 0;
  for (const note of segments) {
    const { noteSamples, gapSamples } = note;
    const attackSamples = Math.max(1, Math.floor(0.006 * SAMPLE_RATE));
    const releaseSamples = Math.max(1, Math.min(noteSamples, Math.floor(0.035 * SAMPLE_RATE)));
    const gain = note.gain ?? 0.16;

    for (let index = 0; index < noteSamples; index += 1) {
      const time = index / SAMPLE_RATE;
      const attack = Math.min(1, index / attackSamples);
      const release = Math.min(1, (noteSamples - 1 - index) / releaseSamples);
      const envelope = Math.sin(Math.PI / 2 * Math.min(attack, release)) ** 2;
      const fundamental = Math.sin(2 * Math.PI * note.frequency * time);
      const harmonic = 0.12 * Math.sin(2 * Math.PI * note.frequency * 2 * time);
      const sample = Math.max(-1, Math.min(1, (fundamental + harmonic) * gain * envelope));
      view.setInt16(44 + outputIndex * 2, Math.round(sample * 32_767), true);
      outputIndex += 1;
    }
    outputIndex += gapSamples;
  }

  return bytes;
}

import type { TodayResponse } from "./types";

/** One action shared by Home and Train. Navigation does not grant API access. */
export function getTrainingAction(today: TodayResponse | null) {
  switch (today?.state) {
    case "diagnostic": return { label: today.answeredChallengeIds?.length ? "Continue starting check" : "Start your check", href: "/(tabs)/train/session" as const, hint: "Open your starting check at the next unanswered question." };
    case "lesson": return { label: "Open today’s insight", href: "/(tabs)/train/lesson" as const, hint: "Read today’s short insight before training." };
    case "training": return { label: today.session?.answeredChallengeIds?.length ? "Continue training" : "Train now", href: "/(tabs)/train/session" as const, hint: "Open your training at the next unanswered question." };
    case "complete": return { label: "Choose a skill", href: "/(tabs)/skills" as const, hint: "Explore skills for another practice session." };
    case "onboarding": return { label: "Set up your learning", href: "/onboarding" as const, hint: "Choose the situations you would like to practise." };
    default: return { label: "Try again", href: null, hint: "Try loading today’s training again." };
  }
}
